(function(){
'use strict';
const C=window.GMCore,V=window.GMVault,$=id=>document.getElementById(id);
let data=null,vaultKey=null,vaultSalt=null,passwordMemory='',iterations=V.ITERATIONS,lastRecord=null,saveQueue=Promise.resolve(),pending=0,saveError=false;
let view='bestiary',filters={q:'',faction:'Todos',grade:'Todos',folder:'all',archived:false},draft=null,editorTab='identity',detailId=null,detailTemplate=false,simpleAction=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(s,max=400)=>String(s??'').slice(0,max),fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const factionClass=f=>f==='Talon'?'faction-talon':f==='Setor Nulo'?'faction-null':'';
const signed=n=>(n>=0?'+':'')+C.round(n),kindName=k=>({basic:'Ataque Básico',skill:'Habilidade',passive:'Passiva',ultimate:'Ultimate'})[k]||'Habilidade';
const option=(v,current,label=v)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;
function safeImage(url){try{if(typeof url!=='string'||!url.trim())return '';if(/^data:image\/(?:png|jpeg|webp|gif);base64,/i.test(url))return url;const parsed=new URL(url,document.baseURI);return ['http:','https:'].includes(parsed.protocol)?parsed.href:''}catch{return ''}}
let toastTimer,characterContext=null;
function toast(message,error=false){const el=$('toast');el.textContent=message;el.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',4200)}
function status(message,error=false){$('saveStatus').textContent=message;$('saveStatus').classList.toggle('error',error)}
function persist(){
 if(!data||!vaultKey)return Promise.resolve();
 const snapshot=C.clone(data),key=vaultKey,salt=vaultSalt,it=iterations;pending++;status('Salvando bestiário…');
 const operation=saveQueue.catch(()=>{}).then(async()=>{
  const record=await V.encrypt(snapshot,key,salt,it);await V.write(record);lastRecord=record;saveError=false;
 }).catch(error=>{saveError=true;status('Não foi possível salvar',true);toast('Não foi possível salvar o bestiário. Exporte um backup antes de fechar.',true);console.error('GM: falha ao salvar',error);throw error}).finally(()=>{pending--;if(!pending&&!saveError)status('Salvo neste navegador')});
 saveQueue=operation;operation.catch(()=>{});return operation;
}
async function unlock(event){
 event.preventDefault();const pass=$('gmPassword').value;$('gateError').textContent='';$('unlockBtn').disabled=true;$('unlockBtn').textContent='Abrindo operação…';
 try{
  if(!await V.checkPassword(pass))throw Error('Senha incorreta. Confira maiúsculas, minúsculas e o sublinhado.');
  const record=await V.read();
  const salt=record?V.fromBase64(record.salt):V.newSalt(),it=record?.iterations??V.ITERATIONS,key=await V.deriveKey(pass,salt,it);
  let loaded;try{loaded=record?C.normalizeState(await V.decrypt(record,key)):C.newState()}catch{throw Error('Não foi possível abrir o bestiário salvo. Nenhum dado foi substituído.')}
  data=loaded;vaultKey=key;vaultSalt=salt;iterations=it;lastRecord=record;passwordMemory=pass;saveError=false;
  $('gmPassword').value='';$('gmPassword').type='password';$('showPassword').setAttribute('aria-pressed','false');$('showPassword').setAttribute('aria-label','Mostrar senha');
  $('gate').hidden=true;$('gmApp').hidden=false;render();$('newEnemyBtn').focus();
  if(!record)persist();
 }catch(error){$('gateError').textContent=error.message||'Não foi possível abrir o modo GM.';$('gmPassword').select()}
 finally{$('unlockBtn').disabled=false;$('unlockBtn').innerHTML='Entrar no modo GM <span class="ico i-arrow right"></span>'}
}
async function lock(){
 if(draft&&$('editorDialog').open)return;
 try{await persist();await saveQueue}catch{return}
 document.querySelectorAll('dialog[open]').forEach(d=>d.close());
 data=null;vaultKey=null;vaultSalt=null;passwordMemory='';lastRecord=null;draft=null;detailId=null;simpleAction=null;
 $('viewContent').innerHTML='';$('folderList').innerHTML='';$('editorFields').innerHTML='';$('livePreview').innerHTML='';$('detailContent').innerHTML='';$('characterContent').innerHTML='';characterContext=null;$('simpleInput').value='';$('gmApp').hidden=true;$('gate').hidden=false;$('gmPassword').focus();
}
function openSimple({title,message='',value='',input=false,confirm='Confirmar',danger=false,action}){
 $('simpleTitle').textContent=title;$('simpleMessage').textContent=message;$('simpleInputLabel').hidden=!input;$('simpleInput').value=value;$('simpleInput').required=input;$('simpleConfirm').textContent=confirm;$('simpleConfirm').className='button '+(danger?'danger':'primary');simpleAction=action;$('simpleDialog').showModal();if(input){$('simpleInput').focus();$('simpleInput').select()}
}
function newFolder(){openSimple({title:'Nova pasta',message:'Organize inimigos por missão, região ou arco da campanha.',input:true,confirm:'Criar pasta',action:name=>{if(!name.trim())return;data.folders.push({id:C.uid(),name:name.trim().slice(0,100)});persist();renderSidebar();if(view==='bestiary')renderView()}})}
function renderSidebar(){
 if($('templateCount'))$('templateCount').textContent=C.TEMPLATES.length;
 $('characterCount').textContent=data.enemies.filter(e=>e.sheetType==='character'&&!e.archived).length;
 $('navCount').textContent=data.enemies.filter(e=>!e.archived).length;$('encounterCount').textContent=data.encounter.entries.length;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 $('folderList').innerHTML=`<div class="folder-row ${filters.folder==='all'?'active':''}"><button data-folder="all"><span class="ico i-grid"></span><span>Todos os inimigos</span></button></div><div class="folder-row ${filters.folder===''?'active':''}"><button data-folder=""><span class="ico i-folder"></span><span>Sem pasta</span></button></div>`+data.folders.map(f=>`<div class="folder-row ${filters.folder===f.id?'active':''}"><button data-folder="${esc(f.id)}"><span class="ico i-folder"></span><span>${esc(f.name)}</span></button><button class="icon-button" data-folder-options="${esc(f.id)}" aria-label="Organizar pasta ${esc(f.name)}">⋯</button></div>`).join('');
}
function render(){renderSidebar();renderView()}
function mobileTools(){return `<div class="mobile-tools" style="display:none"><button class="button subtle small" data-action="new-folder"><span class="ico i-folder"></span>Nova pasta</button><button class="button subtle small" data-action="import">Importar</button><button class="button subtle small" data-action="backup">Backup</button></div>`}
function renderView(){
 const title={bestiary:['ARQUIVO DE AMEAÇAS','Seu bestiário','De uma patrulha da Talon ao chefe da sua próxima missão.'],templates:['ARSENAL DE IDEIAS','Modelos prontos','Escolha uma base para criar uma ameaça com a cara da sua campanha.'],characters:['PERSONAGENS DA CAMPANHA','Fichas de personagem','Heróis, vilões e aliados com a mesma leitura da ficha de player.'],encounter:['OPERAÇÃO EM ANDAMENTO','Seu encontro','Cada inimigo acompanha a própria vida, energia e condições.']}[view];
 $('pageEyebrow').textContent=title[0];$('pageTitle').innerHTML=esc(title[1])+'<span>.</span>';$('pageSubtitle').textContent=title[2];
 $('newEnemyLabel').textContent=view==='characters'?'Criar personagem':'Criar inimigo';
 if(view==='encounter'){renderEncounter();return}
 if(view==='characters'){renderCharacters();return}
 const active=data.enemies.filter(e=>!e.archived),metrics=view==='bestiary'?`<div class="metrics">${[['∑',active.length,'Inimigos no bestiário'],['T',active.filter(e=>e.faction==='Talon').length,'Talon'],['N',active.filter(e=>e.faction==='Setor Nulo').length,'Setor Nulo'],['III',active.filter(e=>e.grade==='Elite'||e.grade==='Chefe').length,'Elites e chefes']].map(([ic,val,label])=>`<div class="metric"><div class="metric-icon">${ic}</div><div><b>${val}</b><small>${label}</small></div></div>`).join('')}</div>`:`<p class="template-note">Modelos criados para o seu RPG. Você pode mudar atributos, habilidades, funções e níveis de ameaça à vontade. Eles só entram no bestiário quando você salva a sua versão.</p>`;
 const folders=view==='bestiary'?`<select class="input" id="folderFilter" aria-label="Filtrar por pasta">${option('all',filters.folder,'Todas as pastas')}${option('',filters.folder,'Sem pasta')}${data.folders.map(f=>option(f.id,filters.folder,f.name)).join('')}</select>`:'';
 $('viewContent').innerHTML=mobileTools()+metrics+`<div class="toolbar" style="${view==='templates'?'margin-top:22px':''}"><label class="search"><span class="ico i-crosshair"></span><input class="input" id="enemySearch" type="search" value="${esc(filters.q)}" placeholder="Buscar por nome, habilidade ou descrição…" aria-label="Buscar inimigos"></label><select class="input" id="gradeFilter" aria-label="Filtrar por categoria">${option('Todos',filters.grade,'Todas as categorias')}${C.GRADES.map(g=>option(g,filters.grade)).join('')}</select>${folders}</div><div class="chips">${['Todos',...C.FACTIONS].map(f=>`<button class="chip ${filters.faction===f?'active':''}" data-faction-filter="${esc(f)}">${esc(f==='Todos'?'Todas as facções':f)}</button>`).join('')}${view==='bestiary'?`<button class="chip ${filters.archived?'active':''}" data-action="archive-filter">Arquivados</button>`:''}</div><div class="result-line"><span id="resultCount"></span><button class="text-button" data-action="clear-filters">Limpar filtros</button></div><div id="cardsContainer"></div>`;
 $('enemySearch').oninput=e=>{filters.q=e.target.value;renderCards()};$('gradeFilter').onchange=e=>{filters.grade=e.target.value;renderCards()};if($('folderFilter'))$('folderFilter').onchange=e=>{filters.folder=e.target.value;renderSidebar();renderCards()};renderCards();
}
function matchEnemy(e){const q=fold(filters.q);return (filters.faction==='Todos'||e.faction===filters.faction)&&(filters.grade==='Todos'||e.grade===filters.grade)&&(!q||fold([e.name,e.summary,e.faction,...e.abilities.map(a=>a.name+' '+a.effect)].join(' ')).includes(q))}
function renderCards(){
 if(!data||view==='encounter'||view==='characters')return;
 let list=view==='templates'?C.TEMPLATES.map(t=>C.fromTemplate(t.key)):data.enemies.filter(e=>e.archived===filters.archived&&(filters.folder==='all'||e.folderId===filters.folder));list=list.filter(matchEnemy);
 $('resultCount').textContent=list.length+(view==='templates'?' modelos disponíveis':' inimigos encontrados');
 if(!list.length){
  const first=!data.enemies.length&&view==='bestiary';
  $('cardsContainer').innerHTML=`<div class="empty-state"><div class="empty-mark"><img src="assets/overwatch-icon.png" alt=""></div><h2>${first?'Sua próxima ameaça começa aqui.':'Nenhuma ameaça por aqui.'}</h2><p>${first?'Monte seu primeiro inimigo do zero ou use um dos modelos para preparar a próxima sessão.':'Experimente outra busca, mude a pasta ou limpe os filtros.'}</p><div><button class="button primary" data-action="${first?'templates':'clear-filters'}">${first?'Explorar modelos':'Limpar filtros'}</button>${first?'<button class="button subtle" data-action="create">Criar do zero</button>':''}</div></div>${first?`<div class="quick-models"><h3 class="template-heading">PARA A PRÓXIMA OPERAÇÃO</h3><div>${['talon-trooper','null-siege','talon-commander'].map(key=>{const t=C.TEMPLATES.find(x=>x.key===key);return `<button class="quick-model ${factionClass(t.faction)}" data-template="${key}"><span class="quick-glyph">${t.faction==='Talon'?'T':'N'}</span><span><b>${esc(t.name)}</b><small>${t.faction} / ${t.grade}</small></span></button>`}).join('')}</div></div>`:''}`;return;
 }
 if(view==='templates'){
  $('cardsContainer').innerHTML=C.FACTIONS.map(f=>{const group=list.filter(e=>e.faction===f);return group.length?`<h2 class="template-heading ${factionClass(f)}">${esc(f.toUpperCase())}<span class="helper">${group.length} modelos</span></h2><div class="enemy-grid">${group.map(e=>enemyCard(e,true)).join('')}</div>`:''}).join('');
 }else $('cardsContainer').innerHTML=`<div class="enemy-grid">${list.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(e=>enemyCard(e)).join('')}</div>`;
}
function enemyArt(e){const image=safeImage(e.portrait);return `<div class="card-art ${e.portraitFit==='contain'?'has-cutout':''}">${image?`<img class="${e.portraitFit==='contain'?'fit-contain':''}" src="${esc(image)}" alt="${esc(e.name)}" loading="lazy">`:'<img class="faction-placeholder" src="assets/overwatch-icon.png" alt="">'}<span class="card-faction">${esc(e.faction.toUpperCase())}</span><span class="card-tier">TIER ${e.tier}</span><span class="card-grade">${esc(e.grade.toUpperCase())}</span></div>`}
function enemyCard(e,template=false){const s=C.stats(e);return `<article class="enemy-card ${e.grade==='Chefe'?'is-boss':''}" data-faction="${esc(e.faction)}">${enemyArt(e)}<div class="card-body"><button class="card-title" ${template?`data-template-detail="${esc(e.templateKey)}"`:`data-open="${esc(e.id)}"`}>${esc(e.name)}</button><div class="card-subtitle">${e.sheetType==='character'?'PERSONAGEM / ':''}${esc(e.role)} / ${e.abilities.filter(a=>a.kind!=='passive').length} ações${e.archived?' / Arquivado':''}</div><p class="card-description">${esc(e.summary||'Ameaça personalizada, pronta para a sua próxima sessão.')}</p><div class="card-stats"><div><small>Vida</small><b>${s.hp}<small style="display:inline;margin-left:3px">HP</small></b></div><div><small>Dano base</small><b>${s.damage}</b></div><div><small>Acerto</small><b>${signed(s.attack)}</b></div></div></div><footer class="card-footer">${template?`<button class="button primary small" data-template="${esc(e.templateKey)}">Usar modelo<span class="ico i-plus"></span></button>`:`<button class="button subtle small" data-open="${esc(e.id)}">Ver ficha</button><button class="button primary small" data-add-encounter="${esc(e.id)}">+ Encontro</button><button class="icon-button" data-edit="${esc(e.id)}" aria-label="Editar ${esc(e.name)}">⋯</button>`}</footer></article>`}
function field(label,key,value,type='text',extra=''){return `<label class="field"><span>${label}</span><input class="input" type="${type}" data-draft="${key}" value="${esc(value)}" ${extra}></label>`}
function draftSelect(label,key,values,current){return `<label class="field"><span>${label}</span><select class="input" data-draft="${key}">${values.map(v=>option(typeof v==='string'?v:v[0],current,typeof v==='string'?v:v[1])).join('')}</select></label>`}
function openEditor(enemy=null,character=false){if($('characterDialog').open)$('characterDialog').close();draft=C.normalize(enemy||C.makeEnemy(character?{name:'Novo personagem',sheetType:'character',grade:'Elite'}:{}));editorTab='identity';if(view==='bestiary'&&filters.folder!=='all'&&!enemy)draft.folderId=filters.folder;$('editorTitle').textContent=data.enemies.some(e=>e.id===draft.id)?(draft.sheetType==='character'?'Editar personagem':'Editar inimigo'):(draft.sheetType==='character'?'Criar personagem':'Criar inimigo');renderEditor();$('editorDialog').showModal()}
function renderEditor(){
 if(!draft)return;document.querySelectorAll('[data-editor-tab]').forEach(b=>{const active=b.dataset.editorTab===editorTab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});
 const e=draft;$('characterEditorTab').hidden=e.sheetType!=='character';$('saveEnemyLabel').textContent=e.sheetType==='character'?'Salvar personagem':'Salvar inimigo';
 if(editorTab==='identity')$('editorFields').innerHTML=`<div class="form-grid">${draftSelect('Tipo de ficha','sheetType',[['enemy','Inimigo / tropa'],['character','Personagem / NPC']],e.sheetType)}${field(e.sheetType==='character'?'Nome do personagem':'Nome do inimigo','name',e.name,'text','required maxlength="150"')}${draftSelect('Facção','faction',C.FACTIONS,e.faction)}${draftSelect('Categoria','grade',C.GRADES,e.grade)}${draftSelect('Função','role',C.ROLES,e.role)}${field('Tier de ameaça','tier',e.tier,'number','min="0" max="10" step="1"')}<label class="field"><span>Pasta</span><select class="input" data-draft="folderId">${option('',e.folderId,'Sem pasta')}${data.folders.map(f=>option(f.id,e.folderId,f.name)).join('')}</select></label><label class="field wide"><span>Resumo / Papel na missão</span><textarea class="input" data-draft="summary" maxlength="5000" placeholder="O que esse inimigo faz e como ele entra na história?">${esc(e.summary)}</textarea></label></div><div class="section-label"><span>Atributos livres</span><button type="button" class="button subtle small" data-action="scale-draft">Usar atributos sugeridos</button></div><p class="helper" style="margin-bottom:11px">O Tier e a categoria orientam a sugestão. Você pode distribuir os atributos livremente.</p><div class="stat-inputs">${C.ATTRS.map(([key,label])=>`<label class="field"><span>${label}</span><input type="number" min="0" max="999" step="1" data-stat="${key}" value="${e.stats[key]}" aria-label="${label} do inimigo"></label>`).join('')}</div><details class="advanced"><summary>Ajustes extras de combate</summary><div class="form-grid">${[['hp','HP adicional'],['damage','Dano adicional'],['reduction','Redução adicional'],['movement','Movimento adicional (m)'],['energy','Energia Máxima adicional'],['attack','Acerto adicional'],['defense','Defesa adicional']].map(([key,label])=>`<label class="field"><span>${label}</span><input class="input" type="number" step="0.5" data-adjust="${key}" value="${e.adjust[key]}"></label>`).join('')}</div></details><details class="advanced"><summary>Valores fixos de HP e Movimento</summary><div class="form-grid"><label class="field"><span>HP Máximo fixo</span><input class="input" type="number" min="1" step="1" data-override="hp" value="${e.overrides?.hp??''}" placeholder="Usar a fórmula normal"></label><label class="field"><span>Movimento fixo (m)</span><input class="input" type="number" min="0" step="0.5" data-override="movement" value="${e.overrides?.movement??''}" placeholder="Usar a fórmula normal"></label><p class="helper wide">Preenchidos, estes valores têm prioridade sobre os atributos e ajustes. Deixe vazio para usar a fórmula normal.</p></div></details><div class="section-label">Retrato do inimigo</div><div class="form-grid"><label class="field wide"><span>Link de imagem</span><input class="input" type="text" inputmode="url" data-draft="portrait" value="${esc(e.portrait.startsWith('data:')?'':e.portrait)}" placeholder="https://…" data-portrait-url></label>${draftSelect('Enquadramento do retrato','portraitFit',[['cover','Preencher'],['contain','Arte inteira']],e.portraitFit||'cover')}</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="button subtle small" data-action="upload-portrait">Carregar imagem</button>${e.portrait?'<button type="button" class="button subtle small" data-action="remove-portrait">Remover retrato</button>':''}</div>`;
 else if(editorTab==='character')$('editorFields').innerHTML=window.GMCharacterSheet.editor(e,option);
 else if(editorTab==='abilities')$('editorFields').innerHTML=`<p class="helper" style="margin:4px 0 16px">Crie ataques, habilidades, passivas e ultimates. Valores automáticos acompanham o Poder; você também pode definir valores fixos.</p><div id="abilityEditors">${e.abilities.map(abilityEditor).join('')}</div><button type="button" class="add-ability" data-action="add-ability">+ Adicionar habilidade ou passiva</button>`;
 else $('editorFields').innerHTML=`<div class="section-label" style="margin-top:10px">Só para o GM</div><p class="helper">Use este espaço para história, personalidade, segredos, encontros planejados, reforços e recompensas.</p><label class="field" style="margin-top:16px"><span>Notas da operação</span><textarea class="input" data-draft="notes" style="min-height:340px" maxlength="60000" placeholder="O que os jogadores ainda não sabem…">${esc(e.notes)}</textarea></label>`;
 bindEditor();renderPreview();
}
function abilityEditor(a,i){return `<section class="ability-editor"><div class="ability-editor-head"><b>${kindName(a.kind)} ${i+1}</b><div><button type="button" class="icon-button" data-ability-up="${i}" aria-label="Mover habilidade para cima" ${i===0?'disabled':''}>↑</button><button type="button" class="icon-button" data-ability-down="${i}" aria-label="Mover habilidade para baixo" ${i===draft.abilities.length-1?'disabled':''}>↓</button><button type="button" class="icon-button" data-ability-remove="${i}" aria-label="Remover habilidade">×</button></div></div><div class="form-grid"><label class="field"><span>Nome</span><input class="input" data-ability="${i}" data-af="name" value="${esc(a.name)}" maxlength="160"></label><label class="field"><span>Categoria</span><select class="input" data-ability="${i}" data-af="kind">${['basic','skill','passive','ultimate'].map(k=>option(k,a.kind,kindName(k))).join('')}</select></label><label class="field"><span>Tipo de efeito</span><select class="input" data-ability="${i}" data-af="output">${['Dano','Cura','Escudo','Controle','Movimento','Utilidade'].map(x=>option(x,a.output)).join('')}</select></label><label class="field"><span>Ação</span><input class="input" data-ability="${i}" data-af="action" value="${esc(a.action)}" placeholder="Padrão, Movimento, Reação…"></label></div><div class="form-grid three"><label class="field"><span>Custo de Energia</span><input class="input" type="number" min="0" max="999" data-ability="${i}" data-af="cost" value="${a.cost}"></label><label class="field"><span>Alcance</span><input class="input" data-ability="${i}" data-af="range" value="${esc(a.range)}"></label><label class="field"><span>Alvo / Área</span><input class="input" data-ability="${i}" data-af="target" value="${esc(a.target)}"></label></div><div class="form-grid"><label class="field"><span>Cálculo do valor</span><select class="input" data-ability="${i}" data-af="mode">${option('auto',a.mode,'Automático')}${option('fixed',a.mode,'Valor fixo')}${option('none',a.mode,'Só descrição')}</select></label><label class="field"><span>${a.mode==='fixed'?'Valor fixo':'Ajuste no valor automático'}</span><input class="input" type="number" step="1" data-ability="${i}" data-af="${a.mode==='fixed'?'amount':'bonus'}" value="${a.mode==='fixed'?a.amount:a.bonus}" ${a.mode==='none'?'disabled':''}></label><label class="field wide"><span>Efeito e regras</span><textarea class="input" data-ability="${i}" data-af="effect" maxlength="30000" placeholder="Descreva o que acontece, as condições e a duração…">${esc(a.effect)}</textarea></label></div><details class="advanced"><summary>Acerto, testes e recarga</summary><div class="form-grid"><label class="field"><span>Rolagem</span><select class="input" data-ability="${i}" data-af="rollMode">${option('attack',a.rollMode,'Teste de ataque')}${option('save',a.rollMode,'Alvo faz um teste')}${option('automatic',a.rollMode,'Sem rolagem de acerto')}${option('description',a.rollMode,'Só descrição')}</select></label><label class="field"><span>Ajuste no acerto</span><input class="input" type="number" data-ability="${i}" data-af="attackBonus" value="${C.num(a.attackBonus)}"></label><label class="field"><span>Quantidade por ação</span><input class="input" data-ability="${i}" data-af="attacksPerAction" value="${esc(a.attacksPerAction??1)}" placeholder="1, 2, X ou 1d6"></label><label class="field"><span>Teste do alvo</span><input class="input" data-ability="${i}" data-af="saveType" value="${esc(a.saveType||'')}" placeholder="Resistência, Destreza…"></label><label class="field"><span>DT fixa</span><input class="input" type="number" min="0" data-ability="${i}" data-af="saveDt" value="${a.saveDt??''}" placeholder="Conforme a descrição"></label><label class="field"><span>Recarga (rodadas)</span><input class="input" type="number" min="0" data-ability="${i}" data-af="cooldownRounds" value="${C.num(a.cooldownRounds)}"></label><label class="field wide"><span>Limite de uso / Observação</span><input class="input" data-ability="${i}" data-af="usage" value="${esc(a.usage||'')}" placeholder="Ex.: 1 vez por combate, somente na Fase 2…"></label></div></details>${draft.sheetType==='character'?`<details class="advanced"><summary>Efeitos na ficha do personagem</summary><div class="form-grid">${[['activateEffect','Ativar efeito',draft.effects],['requiresEffect','Requer efeito ativo',draft.effects],['forbidsEffect','Indisponível com efeito',draft.effects],['restoreResource','Restaurar reserva',draft.resources],['valueResource','Valor igual à reserva',draft.resources]].map(([key,label,entries])=>`<label class="field"><span>${label}</span><select class="input" data-ability="${i}" data-af="${key}">${option('',a[key]||'','Nenhum')}${entries.map(x=>option(x.id,a[key],x.name)).join('')}</select></label>`).join('')}<label class="field"><span>Energia gerada ao usar</span><input class="input" type="number" min="0" data-ability="${i}" data-af="generatesEnergy" value="${C.num(a.generatesEnergy)}"></label></div></details>`:''}<p class="helper" data-ability-preview="${i}">${esc(abilityValueLabel(draft,a))}</p></section>`}
function abilityRollLabel(e,a){
 const parts=[];
 if(a.rollMode==='attack')parts.push('Acerto: 1d20 '+signed(C.attackValue(e,a)));
 else if(a.rollMode==='save'){const dt=a.saveDt??(a.output==='Controle'&&a.mode==='auto'?C.abilityValue(e,a):null);parts.push('Teste: '+(a.saveType||'conforme o efeito')+(dt===null?'':' • DT '+dt))}
 else if(a.rollMode==='automatic')parts.push('Sem rolagem de acerto');
 if(a.attacksPerAction&&String(a.attacksPerAction)!=='1')parts.push('Quantidade por ação: '+a.attacksPerAction);
 if(a.cooldownRounds)parts.push('Recarga: '+a.cooldownRounds+' rodadas');
 if(a.usage)parts.push(a.usage);
 return parts.join(' / ');
}
function abilityValueLabel(e,a){const val=C.abilityValue(e,a);return val===null?'Efeito definido na descrição.':e.sheetType==='character'?`${a.output}: ${val}${C.multiplier(e,({Dano:'damage',Cura:'healing',Escudo:'shield'})[a.output]||'none')!==1?' • escala ×'+C.multiplier(e,({Dano:'damage',Cura:'healing',Escudo:'shield'})[a.output]||'none'):''}`:a.output==='Controle'?`DT ${val} • 10 + Poder + Energia investida`:a.mode==='fixed'?`${a.output}: ${val} • valor fixo`:`${a.output}: ${val} • Poder × 5${a.bonus?` ${signed(a.bonus)}`:''}${a.kind!=='basic'&&a.cost?` + ${a.cost} × 15 Energia`:''}`}
function bindEditor(){
 $('editorFields').querySelectorAll('[data-profile]').forEach(input=>input.oninput=()=>{draft.profile[input.dataset.profile]=input.value});
 $('editorFields').querySelectorAll('[data-multiplier]').forEach(input=>input.oninput=()=>{draft.multipliers[input.dataset.multiplier]=C.clamp(input.value,.1,20);renderPreview()});
 $('editorFields').querySelectorAll('[data-resource-edit]').forEach(input=>input.oninput=input.onchange=()=>{const resource=draft.resources[C.num(input.dataset.resourceEdit)];resource[input.dataset.rf]=input.type==='number'?C.clamp(input.value,0,999999):input.value;renderPreview()});
 $('editorFields').querySelectorAll('[data-effect-edit]').forEach(input=>input.oninput=input.onchange=()=>{const effect=draft.effects[C.num(input.dataset.effectEdit)],key=input.dataset.ef;if(key.startsWith('bonuses.'))effect.bonuses[key.slice(8)]=C.num(input.value);else effect[key]=input.type==='number'?C.num(input.value):input.value;renderPreview()});
 $('editorFields').querySelectorAll('[data-draft]').forEach(input=>input.oninput=()=>{const key=input.dataset.draft;if(input.hasAttribute('data-portrait-url')&&draft.portrait.startsWith('data:')&&!input.value)return;draft[key]=key==='tier'?C.clamp(input.value,0,10):input.value;if(key==='sheetType'){renderEditor();return}renderPreview()});
 $('editorFields').querySelectorAll('select[data-draft]').forEach(input=>input.onchange=input.oninput);
 $('editorFields').querySelectorAll('[data-stat]').forEach(input=>input.oninput=()=>{draft.stats[input.dataset.stat]=C.clamp(input.value,0,999);renderPreview()});
 $('editorFields').querySelectorAll('[data-override]').forEach(input=>input.oninput=()=>{if(!draft.overrides)draft.overrides={hp:null,movement:null};draft.overrides[input.dataset.override]=input.value===''?null:C.clamp(input.value,input.dataset.override==='hp'?1:0,999999);renderPreview()});
 $('editorFields').querySelectorAll('[data-adjust]').forEach(input=>input.oninput=()=>{draft.adjust[input.dataset.adjust]=C.num(input.value);renderPreview()});
 $('editorFields').querySelectorAll('[data-ability]').forEach(input=>{const write=()=>{const a=draft.abilities[C.num(input.dataset.ability)],key=input.dataset.af;a[key]=key==='saveDt'&&input.value===''?null:input.type==='number'?C.num(input.value):input.value;if(key==='kind'){if(a.kind==='passive'){a.mode='none';a.cost=0;a.action='Passiva'}else if(a.action==='Passiva'){a.action='Ação Padrão';a.mode='auto';if(a.kind==='ultimate')a.cost=10}renderEditor();return}if(key==='mode'){renderEditor();return}const preview=$('editorFields').querySelector(`[data-ability-preview="${input.dataset.ability}"]`);if(preview)preview.textContent=abilityValueLabel(draft,a);renderPreview()};input.oninput=write;if(input.tagName==='SELECT')input.onchange=write});
}
function renderPreview(){if(!draft)return;const e=draft,s=C.stats(e);$('livePreview').innerHTML=`<div class="preview-card ${factionClass(e.faction)}">${enemyArt(e)}<div class="preview-name">${esc(e.name||'Novo inimigo')}</div><div class="preview-role">${esc(e.role)} / ${esc(e.grade)} / Tier ${e.tier}</div><div class="preview-attrs">${C.ATTRS.map(([key,label])=>`<div><small>${label}</small><b>${e.stats[key]}</b></div>`).join('')}</div><div class="preview-derived">${[['Vida',s.hp+' HP'],['Dano base',s.damage],['Acerto',signed(s.attack)],['Defesa',signed(s.defense)],['Redução',s.reduction],['Movimento',s.movement+'m'],['Energia Máxima',s.energy],['DT base',s.dt]].map(([label,val])=>`<div><small>${label}</small><b>${val}</b></div>`).join('')}</div></div><p class="preview-tip">${e.overrides?.hp!=null?'HP fixo: '+s.hp+'.':'HP = base da função + Vida × 50.'}<br>${e.overrides?.movement!=null?'Movimento fixo: '+s.movement+'m.<br>':''}Dano base = Poder × 5. Redução = Resistência × 2.<br>Os ajustes extras entram nos valores acima.${e.sheetType==='character'?'<br>Os multiplicadores de combate são aplicados aos valores acima uma única vez.':''}</p>`}
async function saveEnemy(event){event.preventDefault();if(!draft)return;const clean=C.normalize(draft);if(!clean.name.trim()){toast('Dê um nome ao inimigo.',true);return}clean.updatedAt=new Date().toISOString();const i=data.enemies.findIndex(e=>e.id===clean.id);if(i<0)data.enemies.push(clean);else data.enemies[i]=clean;const saving=persist();$('editorDialog').close();draft=null;view=clean.sheetType==='character'?'characters':'bestiary';filters.archived=clean.archived;filters.folder='all';filters.q='';filters.faction='Todos';filters.grade='Todos';render();try{await saving;toast(clean.sheetType==='character'?'Personagem salvo.':'Inimigo salvo no bestiário.');if(clean.sheetType==='character')openCharacter(clean.id)}catch{}}
function openDetail(id,template=false){
 detailId=id;detailTemplate=template;const e=template?C.fromTemplate(id):data.enemies.find(x=>x.id===id);if(!e)return;if(e.sheetType==='character'){openCharacter(id,template?'template':'saved');return}const s=C.stats(e);
 $('detailContent').innerHTML=`<header class="detail-top ${factionClass(e.faction)}"><button type="button" class="icon-button close" data-close="detailDialog" aria-label="Fechar ficha">×</button><span class="eyebrow" style="color:#8ca8c0">${template?'MODELO DE AMEAÇA':'ARQUIVO DO GM'}</span>${safeImage(e.portrait)?`<div class="detail-visual"><img src="${esc(safeImage(e.portrait))}" alt="${esc(e.name)}" class="${e.portraitFit==='contain'?'fit-contain':''}"></div>`:''}<h2 id="detailTitle">${esc(e.name)}</h2><div class="detail-tags"><span class="tag">${esc(e.faction)}</span><span class="tag">${esc(e.grade)}</span><span class="tag">${esc(e.role)}</span><span class="tag">Tier ${e.tier}</span>${e.archived?'<span class="tag">Arquivado</span>':''}</div><p>${esc(e.summary)}</p></header><div class="detail-body"><div class="detail-stats">${[['Vida',s.hp+' HP'],['Dano base',s.damage],['Acerto',signed(s.attack)],['Defesa',signed(s.defense)],['Redução',s.reduction],['Movimento',s.movement+'m'],['Energia Máxima',s.energy],['DT base',s.dt]].map(([label,val])=>`<div><small>${label}</small><b>${val}</b></div>`).join('')}</div><div class="detail-attrs">${C.ATTRS.map(([key,label])=>`<span>${label} <b>${e.stats[key]}</b></span>`).join('')}</div>${e.abilities.length?e.abilities.map(a=>`<section class="read-ability ${a.kind}"><h3>${esc(a.name||kindName(a.kind))}</h3><div class="ability-meta">${esc([kindName(a.kind),a.action,a.range,a.target,a.cost?`${a.cost} Energia`:'Sem custo',abilityRollLabel(e,a)].filter(Boolean).join(' / '))}</div>${C.abilityValue(e,a)!==null?`<div class="ability-number">${esc(abilityValueLabel(e,a))}</div>`:''}<p>${esc(C.abilityText(e,a)||'Sem descrição adicional.')}</p></section>`).join(''):'<p class="helper">Nenhuma habilidade cadastrada.</p>'}${e.notes?`<div class="notes-box"><b>NOTAS DO GM</b>\n${esc(e.notes)}</div>`:''}</div><footer class="modal-footer"><div class="detail-actions" style="width:100%">${template?`<button class="button primary" data-template="${esc(e.templateKey)}">Usar este modelo</button>`:`<button class="button primary" data-add-encounter="${esc(e.id)}">+ Encontro</button><button class="button subtle" data-edit="${esc(e.id)}">Editar</button><button class="button subtle" data-duplicate="${esc(e.id)}">Duplicar</button><button class="button subtle" data-export-enemy="${esc(e.id)}">Exportar JSON</button><button class="button subtle" data-archive="${esc(e.id)}">${e.archived?'Restaurar':'Arquivar'}</button>${e.archived?`<button class="button danger" data-delete-enemy="${esc(e.id)}">Excluir</button>`:''}`}</div></footer>`;
 if(!$('detailDialog').open)$('detailDialog').showModal();
}
function renderCharacters(){
 $('viewContent').innerHTML=mobileTools()+`<div class="character-intro"><div><span class="eyebrow">ELENCO DA CAMPANHA</span><h2>Quem faz parte da sua história?</h2><p>Crie personagens com atributos, retrato, recursos, passivas e Ultimate. Importe uma ficha de player para transformá-la em um NPC.</p></div><img src="assets/overwatch-icon.png" alt="" aria-hidden="true"></div><div class="toolbar"><label class="search"><span class="ico i-crosshair"></span><input class="input" id="characterSearch" type="search" value="${esc(filters.q)}" placeholder="Buscar personagem…" aria-label="Buscar personagens"></label><button class="chip ${filters.archived?'active':''}" data-action="archive-filter">Arquivados</button></div><div id="characterCards"></div>`;
 $('characterSearch').oninput=event=>{filters.q=event.target.value;renderCharacterCards()};renderCharacterCards();
}
function renderCharacterCards(){
 const q=fold(filters.q),matches=e=>!q||fold([e.name,e.summary,e.profile?.alias,e.profile?.affiliation].join(' ')).includes(q);
 const saved=data.enemies.filter(e=>e.sheetType==='character'&&e.archived===filters.archived&&matches(e)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
 const models=C.TEMPLATES.filter(e=>e.sheetType==='character').map(t=>C.fromTemplate(t.key)).filter(matches);
 $('characterCards').innerHTML=`<h2 class="template-heading">SEUS PERSONAGENS <span class="helper">${saved.length} fichas</span></h2>${saved.length?`<div class="enemy-grid character-grid">${saved.map(e=>enemyCard(e)).join('')}</div>`:`<div class="character-empty"><span class="ico i-shield"></span><div><h3>${filters.archived?'Nenhum personagem arquivado.':'Sua campanha tem espaço para novas histórias.'}</h3><p>${q?'Experimente outro nome.':'Crie um NPC ou escolha uma ficha pronta abaixo.'}</p></div><button class="button subtle" data-action="create-character">Criar personagem</button></div>`}${!filters.archived&&models.length?`<h2 class="template-heading character-model-heading">PERSONAGENS PRONTOS <span class="helper">Salve uma cópia para editar e jogar</span></h2><div class="enemy-grid character-grid">${models.map(e=>enemyCard(e,true)).join('')}</div>`:''}`;
}
function characterSelection(){
 if(!characterContext)return null;
 if(characterContext.kind==='template')return {enemy:characterContext.enemy,combat:characterContext.enemy.sheetState,readonly:true};
 if(characterContext.kind==='encounter'){const row=data.encounter.entries.find(r=>r.id===characterContext.id);return row?{enemy:row.snapshot,combat:row,readonly:false}:null}
 const enemy=data.enemies.find(e=>e.id===characterContext.id);return enemy?{enemy,combat:enemy.sheetState,readonly:false}:null;
}
function openCharacter(id,kind='saved'){
 characterContext={id,kind,tab:'summary',roll:'',enemy:kind==='template'?C.fromTemplate(id):null};renderCharacter();
 if(!$('characterDialog').open)$('characterDialog').showModal();
}
function renderCharacter(){
 const selected=characterSelection();if(!selected)return;
 const {enemy,combat,readonly}=selected;if(!readonly)C.runtime(enemy,combat);
 $('characterContent').innerHTML=window.GMCharacterSheet.render(enemy,{readonly,combat,tab:characterContext.tab,roll:characterContext.roll,rollLabel:abilityRollLabel,round:characterContext.kind==='encounter'?data.encounter.round:undefined,encounter:characterContext.kind==='encounter'});
}
function saveCharacter(){
 const selected=characterSelection();if(!selected||selected.readonly)return;
 selected.enemy.updatedAt=new Date().toISOString();persist();renderSidebar();if(view==='characters')renderCharacterCards();if(view==='encounter')renderEncounter();renderCharacter();
}
function characterResource(selected,key,value){
 const {enemy,combat}=selected,max=C.stats(enemy);
 if(key==='hp'||key==='energy')combat[key]=C.clamp(value,0,max[key]);
 else if(key.startsWith('resource:')){const id=key.slice(9);if(enemy.resources.some(r=>r.id===id))enemy.sheetState.resources[id]=C.clamp(value,0,C.resourceMax(enemy,id))}
}
function handleCharacterClick(d){
 const keys=['charAdjust','charFill','charEffect','charUse','charAttack','charRoll','charNextRound','charExtend'];
 if(!keys.some(k=>Object.prototype.hasOwnProperty.call(d,k)))return false;
 const selected=characterSelection();if(!selected)return true;const {enemy,combat,readonly}=selected;
 if(d.charRoll||d.charAttack){
  const a=d.charAttack?enemy.abilities.find(x=>x.id===d.charAttack):null,key=d.charRoll,die=Math.floor(Math.random()*20)+1,s=C.stats(enemy),bonus=a?C.attackValue(enemy,a):key==='precision'?s.attack:key==='dexterity'?s.defense:C.num(enemy.stats[key]);
  characterContext.roll=(a?a.name:({precision:'Ataque',dexterity:'Destreza',resistance:'Resistência'})[key])+`: ${die} ${signed(bonus)} = ${C.round(die+bonus)}`;renderCharacter();return true;
 }
 if(readonly)return true;
 if(d.charAdjust){const key=d.charAdjust,current=key==='hp'||key==='energy'?combat[key]:enemy.sheetState.resources[key.slice(9)]||0;characterResource(selected,key,C.num(current)+C.num(d.delta))}
 else if(d.charFill){const key=d.charFill;characterResource(selected,key,key==='hp'||key==='energy'?C.stats(enemy)[key]:C.resourceMax(enemy,key.slice(9)))}
 else if(d.charEffect){const f=enemy.effects.find(x=>x.id===d.charEffect);if(f&&(!f.requiresEffect||enemy.sheetState.activeEffects.includes(f.requiresEffect)))C.toggleEffect(enemy,f.id);C.runtime(enemy,combat)}
 else if(d.charUse){const a=enemy.abilities.find(x=>x.id===d.charUse);if(a)try{const value=C.useAbility(enemy,a,combat);characterContext.roll=a.name+' usada'+(value!==null?' · '+a.output+': '+value:'')+'. Recursos e efeitos atualizados.'}catch(error){characterContext.roll=error.message}}
 else if(d.charExtend){const f=enemy.effects.find(x=>x.id===d.charExtend);if(f){enemy.sheetState.durations[f.id]=C.clamp(C.num(enemy.sheetState.durations[f.id])+1,1,99);if(f.requiresEffect)enemy.sheetState.durations[f.requiresEffect]=Math.max(enemy.sheetState.durations[f.id],C.num(enemy.sheetState.durations[f.requiresEffect]))}}
 else if(Object.prototype.hasOwnProperty.call(d,'charNextRound')){if(characterContext.kind==='encounter')advanceEncounterRound();else C.nextCharacterRound(enemy,combat);characterContext.roll='Rodada '+(characterContext.kind==='encounter'?data.encounter.round:enemy.sheetState.round)+' · Energia, recargas e durações atualizadas.'}
 saveCharacter();return true;
}
function syncCharacterInput(input){
 const selected=characterSelection();if(!selected||selected.readonly||input.value==='')return false;
 if(input.dataset.charValue){
  const key=input.dataset.charValue;characterResource(selected,key,C.num(input.value));
  const max=key==='hp'||key==='energy'?C.stats(selected.enemy)[key]:C.resourceMax(selected.enemy,key.slice(9)),value=key==='hp'||key==='energy'?selected.combat[key]:selected.enemy.sheetState.resources[key.slice(9)],box=input.closest('.sheet-resource'),fmt=n=>C.round(n).toLocaleString('pt-BR');
  box.querySelector('.sheet-resource-head strong').innerHTML=fmt(value)+' <small>/ '+fmt(max)+'</small>';box.querySelector('.sheet-bar i').style.width=(max?value/max*100:0)+'%';box.querySelector('.sheet-bar span').textContent=fmt(value)+' / '+fmt(max);
 }else {
  const id=input.dataset.charDuration;selected.enemy.sheetState.durations[id]=Math.round(C.clamp(input.value,1,99));const f=selected.enemy.effects.find(f=>f.id===id);if(f?.requiresEffect)selected.enemy.sheetState.durations[f.requiresEffect]=Math.max(selected.enemy.sheetState.durations[id],C.num(selected.enemy.sheetState.durations[f.requiresEffect]));
 }
 return true;
}
document.addEventListener('input',event=>{const input=event.target;if(input.matches('[data-char-value],[data-char-duration]')&&syncCharacterInput(input))persist()});
document.addEventListener('change',event=>{const input=event.target;if(input.matches('[data-char-value],[data-char-duration]')&&syncCharacterInput(input))saveCharacter()});
function advanceEncounterRound(){data.encounter.round++;for(const row of data.encounter.entries)if(row.snapshot.sheetType==='character')C.nextCharacterRound(row.snapshot,row);else if(row.hp>0)row.energy=C.clamp(row.energy+2,0,C.stats(row.snapshot).energy)}

function addEncounter(id){const enemy=data.enemies.find(x=>x.id===id);if(!enemy)return;const count=data.encounter.entries.filter(row=>row.enemyId===id).length;const entry=C.spawn(enemy,count+1);entry.snapshot.sheetState.round=data.encounter.round;data.encounter.entries.push(entry);persist();renderSidebar();if(view==='encounter')renderEncounter();if(characterContext){characterContext.roll=enemy.name+' adicionado ao encontro.';renderCharacter()}else toast(enemy.name+' adicionado ao encontro.')}
function renderEncounter(){
 const encounter=data.encounter;
 $('viewContent').innerHTML=mobileTools()+`<section class="encounter-top"><label class="encounter-name"><input class="input" value="${esc(encounter.name)}" aria-label="Nome do encontro" id="encounterName" maxlength="200"></label><div class="round-counter">Rodada <b>${encounter.round}</b></div><button class="button primary small" data-action="next-round">Próxima rodada</button><button class="button subtle small" data-action="clear-encounter">Limpar encontro</button></section>${encounter.entries.length?`<div class="encounter-list">${[...encounter.entries].sort((a,b)=>b.initiative-a.initiative).map(combatantCard).join('')}</div><p class="encounter-hint">Próxima rodada concede +2 Energia aos inimigos com HP acima de 0, respeitando o máximo. Ajuste condições e efeitos com duração conforme as regras do encontro. Adicione mais inimigos pelo bestiário.</p>`:`<div class="empty-state"><div class="empty-mark">VS</div><h2>Prepare o confronto.</h2><p>Use “+ Encontro” em um inimigo do bestiário. Adicione várias cópias para montar uma patrulha, uma tropa ou a guarda de um chefe.</p><div><button class="button primary" data-action="bestiary">Abrir bestiário</button></div></div>`}`;
 $('encounterName').onchange=e=>{data.encounter.name=e.target.value||'Encontro';persist()};
 $('viewContent').querySelectorAll('[data-combat-value]').forEach(input=>input.onchange=()=>{const row=encounter.entries.find(r=>r.id===input.dataset.combatId);if(!row)return;const max=C.stats(row.snapshot),k=input.dataset.combatValue;row[k]=k==='initiative'?C.clamp(input.value,-999,999):C.clamp(input.value,0,k==='hp'?max.hp:max.energy);persist();renderEncounter()});
 $('viewContent').querySelectorAll('[data-combat-condition]').forEach(select=>select.onchange=()=>{const row=encounter.entries.find(r=>r.id===select.dataset.combatCondition);if(row&&select.value&&!row.conditions.includes(select.value)){row.conditions.push(select.value);persist();renderEncounter()}});
}
function combatantCard(row){const e=row.snapshot,s=C.stats(e),pct=s.hp?row.hp/s.hp*100:0;return `<article class="combatant ${factionClass(e.faction)} ${row.hp===0?'down':''}"><header class="combatant-head"><div><h3>${esc(row.name)}</h3><small>${esc(e.faction)} / ${esc(e.grade)} / Tier ${e.tier}${row.hp===0?' / Fora de combate':''}</small></div><div><label class="initiative">Iniciativa<input class="input" type="number" value="${row.initiative}" data-combat-value="initiative" data-combat-id="${esc(row.id)}" aria-label="Iniciativa de ${esc(row.name)}"></label><button class="icon-button" data-remove-combat="${esc(row.id)}" aria-label="Remover ${esc(row.name)} do encontro">×</button></div></header><div class="combatant-grid"><section><div class="hp-line">VIDA<b>${row.hp} / ${s.hp}</b></div><div class="hp-bar"><div style="width:${pct}%"></div></div><div class="resource-controls">${[-25,-10,10,25].map(delta=>`<button data-combat-adjust="${esc(row.id)}" data-resource="hp" data-delta="${delta}" aria-label="${delta>0?'Curar':'Causar'} ${Math.abs(delta)} HP em ${esc(row.name)}">${signed(delta)}</button>`).join('')}<input class="input current-input" type="number" min="0" max="${s.hp}" value="${row.hp}" data-combat-value="hp" data-combat-id="${esc(row.id)}" aria-label="HP atual de ${esc(row.name)}"></div></section><section><div class="hp-line">ENERGIA<b>${row.energy} / ${s.energy}</b></div><div class="hp-bar"><div style="width:${s.energy?row.energy/s.energy*100:0}%;background:#e9a343"></div></div><div class="resource-controls">${[-1,1,2].map(delta=>`<button data-combat-adjust="${esc(row.id)}" data-resource="energy" data-delta="${delta}" aria-label="${signed(delta)} Energia de ${esc(row.name)}">${signed(delta)}</button>`).join('')}<input class="input current-input" type="number" min="0" max="${s.energy}" value="${row.energy}" data-combat-value="energy" data-combat-id="${esc(row.id)}" aria-label="Energia atual de ${esc(row.name)}"></div></section></div><div class="combatant-stats"><span>Dano <b>${s.damage}</b></span><span>Acerto <b>${signed(s.attack)}</b></span><span>Defesa <b>${signed(s.defense)}</b></span><span>Redução <b>${s.reduction}</b></span><span>Movimento <b>${s.movement}m</b></span></div><footer class="combatant-bottom">${row.conditions.map(c=>`<button class="condition-pill" data-remove-condition="${esc(row.id)}" data-condition="${esc(c)}" aria-label="Remover ${esc(c)} de ${esc(row.name)}">${esc(c)} ×</button>`).join('')}<select class="input" data-combat-condition="${esc(row.id)}" aria-label="Adicionar condição em ${esc(row.name)}"><option value="">+ Condição</option>${C.CONDITIONS.filter(c=>!row.conditions.includes(c)).map(c=>option(c,'')).join('')}</select><button class="button subtle small" data-combat-sheet="${esc(row.id)}">Ver habilidades</button></footer></article>`}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function exportBackup(){if(!data)return;try{const record=await V.encrypt(C.clone(data),vaultKey,vaultSalt,iterations);download('Overwatch_GM_Backup_'+new Date().toISOString().slice(0,10)+'.json',record);toast('Backup exportado. A mesma senha abre os dados.')}catch(error){toast('Não foi possível exportar o backup: '+error.message,true)}}
function exportEnemy(id){const e=data.enemies.find(x=>x.id===id);if(e)download('NPC_'+e.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/gi,'_').slice(0,80)+'.json',{format:'overwatch-rpg-gm-enemies',version:1,enemies:[e],folders:data.folders.filter(f=>f.id===e.folderId)})}
async function importFile(file){
 if(!file)return;if(file.size>40*1024*1024)throw Error('O arquivo precisa ter até 40 MB.');
 let raw=JSON.parse(await file.text()),incoming;
 if(raw.format==='overwatch-rpg-gm-vault'){
  const key=await V.deriveKey(passwordMemory,V.fromBase64(raw.salt),raw.iterations);raw=await V.decrypt(raw,key);incoming=C.normalizeState(raw);
 }else if(Array.isArray(raw.heroes))incoming=C.normalizeState({enemies:raw.heroes.map(C.fromHero),folders:[]});
 else if(Array.isArray(raw.enemies))incoming=C.normalizeState(raw);
 else if(raw.name&&(raw.stats||raw.attrs))incoming=C.normalizeState({enemies:[C.normalize(raw)],folders:[]});
 else throw Error('Este JSON não contém inimigos ou um backup compatível.');
 if(data.enemies.length+incoming.enemies.length>3000)throw Error('O bestiário comporta até 3.000 fichas.');
 if(data.encounter.entries.length+incoming.encounter.entries.length>300)throw Error('O encontro comporta até 300 participantes.');
 const folderMap=new Map(),enemyMap=new Map();
 for(const f of incoming.folders){let folder=data.folders.find(x=>x.name===f.name);if(!folder){folder={id:C.uid(),name:f.name};data.folders.push(folder)}folderMap.set(f.id,folder.id)}
 for(const original of incoming.enemies){const e=C.clone(original),prior=e.id;e.id=C.uid();e.folderId=folderMap.get(e.folderId)||'';e.updatedAt=new Date().toISOString();data.enemies.push(e);enemyMap.set(prior,e.id)}
 for(const original of incoming.encounter.entries){const row=C.clone(original);row.id=C.uid();row.enemyId=enemyMap.get(row.enemyId)||row.enemyId;data.encounter.entries.push(row)}
 await persist();view=incoming.enemies.length&&incoming.enemies.every(e=>e.sheetType==='character')?'characters':'bestiary';filters={q:'',faction:'Todos',grade:'Todos',folder:'all',archived:false};render();toast(incoming.enemies.length+' inimigos importados. As fichas existentes foram mantidas.');
}
async function uploadPortrait(file){
 if(!file||!draft)return;if(!file.type.startsWith('image/'))throw Error('Escolha uma imagem.');if(file.size>12*1024*1024)throw Error('Escolha uma imagem de até 12 MB.');
 const id=draft.id,bitmap=await createImageBitmap(file),ratio=Math.min(1,800/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();if(draft?.id===id){draft.portrait=canvas.toDataURL('image/webp',.85);renderEditor()}
}

$('unlockForm').onsubmit=unlock;
$('showPassword').onclick=()=>{const showing=$('gmPassword').type==='password';$('gmPassword').type=showing?'text':'password';$('showPassword').setAttribute('aria-pressed',String(showing));$('showPassword').setAttribute('aria-label',showing?'Ocultar senha':'Mostrar senha')};
$('lockBtn').onclick=lock;$('newEnemyBtn').onclick=()=>openEditor(null,view==='characters');$('newFolderBtn').onclick=newFolder;$('importBtn').onclick=()=>$('importFile').click();$('backupBtn').onclick=exportBackup;
$('enemyForm').onsubmit=saveEnemy;$('simpleForm').onsubmit=event=>{event.preventDefault();const value=$('simpleInput').value,action=simpleAction;simpleAction=null;$('simpleDialog').close();if(action)action(value)};
$('editorDialog').addEventListener('close',()=>{draft=null;$('editorFields').innerHTML='';$('livePreview').innerHTML=''});
$('characterDialog').addEventListener('close',()=>{characterContext=null;$('characterContent').innerHTML=''});
 $('detailDialog').addEventListener('close',()=>{detailId=null;$('detailContent').innerHTML=''});
$('importFile').onchange=async event=>{try{await importFile(event.target.files[0])}catch(error){toast(error.message||'Não foi possível importar esse JSON.',true)}event.target.value=''};
$('portraitFile').onchange=async event=>{try{await uploadPortrait(event.target.files[0])}catch(error){toast(error.message||'Não foi possível carregar a imagem.',true)}event.target.value=''};
document.addEventListener('click',event=>{
 const close=event.target.closest('[data-close]');if(close){$(close.dataset.close)?.close();return}
 if(!data)return;
 const button=event.target.closest('button');if(!button)return;
 const d=button.dataset;
 if(d.view){view=d.view;filters={q:'',faction:'Todos',grade:'Todos',folder:'all',archived:false};render();return}
 if(d.folder!==undefined){filters.folder=d.folder;view='bestiary';render();return}
 if(d.folderOptions){const folder=data.folders.find(f=>f.id===d.folderOptions);if(folder)openSimple({title:'Renomear pasta',value:folder.name,input:true,confirm:'Salvar nome',message:'As fichas da pasta serão mantidas.',action:name=>{if(name.trim())folder.name=name.trim().slice(0,100);persist();render()}});return}
 if(d.factionFilter){filters.faction=d.factionFilter;document.querySelectorAll('[data-faction-filter]').forEach(b=>b.classList.toggle('active',b.dataset.factionFilter===filters.faction));renderCards();return}
 if(d.editorTab){editorTab=d.editorTab;renderEditor();return}
 if(d.charTab){characterContext.tab=d.charTab;renderCharacter();return}
 if(handleCharacterClick(d))return;
 if(d.removeResource!==undefined){const removed=draft.resources.splice(C.num(d.removeResource),1)[0];delete draft.sheetState.resources[removed.id];for(const a of draft.abilities)for(const k of ['restoreResource','valueResource'])if(a[k]===removed.id)a[k]='';for(const f of draft.effects)if(f.grantResource===removed.id)f.grantResource='';renderEditor();return}
 if(d.removeEffect!==undefined){const removed=draft.effects.splice(C.num(d.removeEffect),1)[0];draft.sheetState.activeEffects=draft.sheetState.activeEffects.filter(x=>x!==removed.id);for(const a of draft.abilities)for(const k of ['activateEffect','requiresEffect','forbidsEffect'])if(a[k]===removed.id)a[k]='';for(const f of draft.effects)if(f.requiresEffect===removed.id)f.requiresEffect='';renderEditor();return}
 if(d.template){const enemy=C.fromTemplate(d.template);if($('detailDialog').open)$('detailDialog').close();openEditor(enemy);return}
 if(d.templateDetail){openDetail(d.templateDetail,true);return}
 if(d.open){openDetail(d.open);return}
 if(d.edit){const enemy=data.enemies.find(e=>e.id===d.edit);if($('detailDialog').open)$('detailDialog').close();if(enemy)openEditor(enemy);return}
 if(d.addEncounter){addEncounter(d.addEncounter);return}
 if(d.duplicate){const enemy=data.enemies.find(e=>e.id===d.duplicate);if(enemy){const copy=C.clone(enemy);copy.id=C.uid();copy.sheetState={hp:null,energy:0,resources:{},activeEffects:[],durations:{},cooldowns:{},round:1};copy.name+=' — Cópia';copy.archived=false;copy.createdAt=new Date().toISOString();$('detailDialog').close();openEditor(copy)}return}
 if(d.exportEnemy){exportEnemy(d.exportEnemy);return}
 if(d.archive){const enemy=data.enemies.find(e=>e.id===d.archive);if(enemy){enemy.archived=!enemy.archived;enemy.updatedAt=new Date().toISOString();persist();$('detailDialog').close();if($('characterDialog').open)$('characterDialog').close();render();toast(enemy.archived?'Inimigo arquivado. Ele continua disponível em Arquivados.':'Inimigo restaurado ao bestiário.')}return}
 if(d.deleteEnemy){const enemy=data.enemies.find(e=>e.id===d.deleteEnemy);if(enemy)openSimple({title:'Excluir inimigo?',message:'A ficha de '+enemy.name+' será excluída do bestiário. Cópias que já estão no encontro serão mantidas.',confirm:'Excluir ficha',danger:true,action:()=>{data.enemies=data.enemies.filter(e=>e.id!==enemy.id);persist();$('detailDialog').close();render()}});return}
 if(d.abilityRemove!==undefined){draft.abilities.splice(C.num(d.abilityRemove),1);renderEditor();return}
 if(d.abilityUp!==undefined||d.abilityDown!==undefined){const index=C.num(d.abilityUp??d.abilityDown),next=index+(d.abilityUp!==undefined?-1:1);if(next>=0&&next<draft.abilities.length){[draft.abilities[index],draft.abilities[next]]=[draft.abilities[next],draft.abilities[index]];renderEditor()}return}
 if(d.combatAdjust){const row=data.encounter.entries.find(r=>r.id===d.combatAdjust);if(row){const s=C.stats(row.snapshot);row[d.resource]=C.clamp(row[d.resource]+C.num(d.delta),0,d.resource==='hp'?s.hp:s.energy);persist();renderEncounter()}return}
 if(d.removeCombat){data.encounter.entries=data.encounter.entries.filter(r=>r.id!==d.removeCombat);persist();renderSidebar();renderEncounter();return}
 if(d.removeCondition){const row=data.encounter.entries.find(r=>r.id===d.removeCondition);if(row){row.conditions=row.conditions.filter(c=>c!==d.condition);persist();renderEncounter()}return}
 if(d.combatSheet){const row=data.encounter.entries.find(r=>r.id===d.combatSheet);if(row){if(row.snapshot.sheetType==='character'){openCharacter(row.id,'encounter');return}const temp=row.snapshot,id=C.uid();const existing=data.enemies.find(e=>e.id===temp.id);if(existing&&JSON.stringify(existing)===JSON.stringify(temp))openDetail(existing.id);else{const original=data.enemies;data.enemies=[...original,{...temp,id}];openDetail(id);data.enemies=original;$('detailContent').querySelector('.detail-actions').innerHTML='<button class="button subtle" data-close="detailDialog">Voltar ao encontro</button>'}}return}
 const action=d.action;if(!action)return;
 if(action==='create')openEditor(null,view==='characters');
 else if(action==='create-character')openEditor(null,true);
 else if(action==='add-resource'){draft.resources.push({id:C.uid(),name:'Nova reserva',max:100,type:'Escudo'});renderEditor()}
 else if(action==='add-effect'){draft.effects.push({id:C.uid(),name:'Novo efeito',description:'',duration:0,grantResource:'',requiresEffect:'',bonuses:{}});renderEditor()}
 else if(action==='templates'||action==='bestiary'){view=action;render()}
 else if(action==='new-folder')newFolder();
 else if(action==='import')$('importFile').click();
 else if(action==='backup')exportBackup();
 else if(action==='archive-filter'){filters.archived=!filters.archived;renderView()}
 else if(action==='clear-filters'){filters={q:'',faction:'Todos',grade:'Todos',folder:'all',archived:false};render()}
 else if(action==='scale-draft'){draft.stats=C.scale(draft.grade,draft.tier);renderEditor()}
 else if(action==='upload-portrait')$('portraitFile').click();
 else if(action==='remove-portrait'){draft.portrait='';renderEditor()}
 else if(action==='add-ability'){draft.abilities.push(C.ability('Nova habilidade'));renderEditor()}
 else if(action==='next-round'){advanceEncounterRound();persist();renderEncounter()}
 else if(action==='clear-encounter')openSimple({title:'Limpar encontro?',message:'Os participantes e os recursos deste encontro serão removidos. Seu bestiário será mantido.',confirm:'Limpar encontro',danger:true,action:()=>{data.encounter={name:'Novo encontro',round:1,entries:[]};persist();render()}});
});
window.addEventListener('beforeunload',event=>{if(pending){event.preventDefault();event.returnValue=''}});
})();
